<script>
// Import the Three.js library
import * as THREE from 'three';

// Define a function to load and animate your glTF scene
async function loadGLTFScene() {
  // Load your GLTF model
  const loader = new THREE.GLTFLoader();
  const gltf = await loader.load('your-model.gltf');

  // Set up your scene, camera, and renderer
  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
  camera.position.z = 5;
  const renderer = new THREE.WebGLRenderer();

  renderer.setSize(window.innerWidth, window.innerHeight);

  document.body.appendChild(renderer.domElement);

  // Create a group to contain all animated meshes
  const animationGroup = new THREE.Group();

  // Add all meshes with the selected animation to the animation group
  gltf.scene.traverse((child) => {
    if (child.animations.length > 0 && child.animation.__actionGroup === gltf.scene) {
      animationGroup.add(child);
    }
  });

  // Add the animation group to your scene
  scene.add(animationGroup);

  // Set up playback controls
  const mixer = new THREE.AnimationMixer(animationGroup);
  const action = mixer.clipAction(gltf.animations[0]);

  // Start playback: replace 'your-animation-name' by the name of the animation you want to play
  action.play();
  mixer.update(0);

  // Render the scene
  function animate() {
    requestAnimationFrame(animate);
    mixer.update(0.02);
    renderer.render(scene, camera);
  }
  animate();
}

