import * as THREE from 'three';
import { GLTF } from 'three/examples/jsm/loaders/GLTFLoader';
import * as glTF from 'gltf';

// Carga el modelo GLB
const loadModel = async (url) => {
  const gltfLoader = new THREE.GLTFLoader();
  const responses = await Promise.all([
    fetch(url),
    fetch(new URL('decoderWorker.js', import.meta.url).href)
  ]);
  const decoder = new Worker(new URL('decoderWorker.js', import.meta.url));

  const gltfBuffer = new glTF.GLTFBuffer(response.res[0].arrayBuffer());
  const gltf = await gltfBuffer.parse();

  return await new Promise((resolve, reject) => {
    gltfLoader.decode(gltf, function (gltf) {
      const animations = gltf.animations;

      const data = {
        scene: gltf.scene,
        animations: []
      };

      // Agrega las animaciones a la lista de datos
      for (let I = 0; I < animations.length; i++) {
        gltf.animations[i].clip = { start: 0, end: 1 }; // setea las temporalidades de las animaciones (por ejemplo, 0 a 1 representan el 100% del tiempo)
        data.animations.push(gltf.animations[i]);
      }

      resolve(data);
    }, error => {
      reject(error);
    }, decoder);
  });
};

// Ejemplo de uso:

const animationHandler = new THREE.AnimationHandler();
const scene = new THREE.Scene();

loadModel('my-glb-model.glb').then(result => {
  scene.add(result.scene);

  // Reproduce automáticamente todas las animaciones del modelo
  animationHandler.load(result.animations);
  animationHandler.onReady(() => {
    animationHandler.play();
  });
});
```

Este ejemplo carga el modelo .glb utilizando Three.GLTFLoader y glTF.js. Luego, carga las animaciones del modelo en Three.AnimationHandler para reproducirlas automáticamente. Nota: Este ejemplo requiere la creación de un worker llamado decoderWorker.js para manejar la decodificación del modelo GLB en el background y asegurarse de la compatibilidad cross-browser.

