  const element = document.querySelector('selector-de-elemento');

  // Evento mouseover
  element.addEventListener('mouseover', function(e) {
    // El código que deseas ejecutar cuando el ratón pase sobre el elemento
  });

  // Evento keyup
  element.addEventListener('keyup', function(e) {
