Luego, debemos escribir la propia implementación de la regla utilizando un esquema de configuración ESLint llamado `.eslintrc.js`:

```js
module.exports = {
  /* Otras configuraciones de ESLint... */

  rules: {
    "vue/lifecycle-modifier": "error",
    "no-method-assign": "error"
  },

  /* Regla Personalizada */
  overrides: [
    {
      files: ["*.vue"],
      customRules: {
        "vue/lifecycle-modifier-no-change-state": {
          meta: {
            fixable: "code",
            docs: {
              description: "Do not modify internal component state in lifecycle hooks.",
              category: "Possible Errors",
              recommended: true
            },
            schema: [
              {
                type: "object",
                properties: {
                  allowCallbacks: {
                    type: "boolean",
                    default: false
                  },
                  allowPromiseChain: {
                    type: "boolean",
                    default: false
                  }
                },
                additionalProperties: false
              }
            ]
          },
          create(context) {
            const allowedModifierKeys = ["beforeCreate", "created", "beforeMount", "mounted", "beforeUpdate", "updated", "activated", "deactivated", "beforeDestroy", "destroyed", "errorCaptured"];
            const { parserServices } = context.options[0].parserOptions;
            const vueParserServices = parserServices && parserServices.vue;

            return {
              "ExpressionStatement": function(node) {
                const { modifiers } = node.callee;

                // Ignore "beforeCreate" and "created" lifecycle hooks, as they don't have access to "this" and can't modify internal state
                if (modifiers && modifiers.some(modifier => allowedModifierKeys.includes(modifier)) && node.expression.operator === "=") {
                  const { start, end } = node.range;

                  // Do not report if the right side of the assignment is one of these:
                  // 1. A simple variable (e.g. `data.foo = bar`)
                  // 2. A callback function, optionally with params, without modifying state (e.g. `vm.foo(async (params) => { ... })`)
                  // 3. A Promise chain where the last promise does not modify state (e.g. `return vm.foo().then(() => { ... }).then(() => { ... })`)
                  const rightSideIsSimpleVariable = VueParserUtils.isAssignmentTargetIdentifier(node.expression.right);
                  const rightSideIsCallbackFnWithoutModifyingState = VueParserUtils.isCallbackExpressionWithoutModifyingState(node.expression.right);
                  const rightSideIsPromiseChainWithoutModifyingState = VueParserUtils.isPromiseChainWithoutModifyingState(node.expression.right, vueParserServices);

                  if (
                    !rightSideIsSimpleVariable &&
                    !rightSideIsCallbackFnWithoutModifyingState &&
                    !rightSideIsPromiseChainWithoutModifyingState
                  ) {
                    const fix = contextErrorMsg(node, "should not modify internal component state");

                    context.report({
                      node,
                      message: "Do not modify internal component state.",
                      fix: function(fixer) {
                        if (rightSideIsCallbackFnWithoutModifyingState) {
                          // Keep the callback function, and disable the fix for this case
                          return [
                            fixer.insertTextBefore(node, "\n/** "),
                            fixer.insertTextAfter(node, " */")
                          ];
                        }

                        return fix(fixer, start, end);
                      },
                      docs: {
                        id: "vue/lifecycle-modifier-no-change-state"
                      }
                    });
                  }
                }
              }
            };
          }
        }
      }
    }
  ]
