Esta regla personalizada verificadores todos los `ExpressionStatement` en archivos de Vue (extensión `*.vue`) en busca de declaraciones de asignación en el cuerpo de una función con modificadores de ciclo de vida. Si se encuentra una declaración con un modificador, el verificador verifica si el lado derecho de la declaración asigna un simple identificador (propiedad de datos o método de la instancia), una función anónima sin modificar el estado interno del componente o una cadena de promesas sin modificar el estado interno del componente. Si es una combinación de estos, se informa el error.

Tenga en cuenta que esta implementación utiliza una librería `VueParserUtils.js` que proporciona funciones para validar ciertos tipos de expresiones simples:

```js
const VueParserUtils = {
  isAssignmentTargetIdentifier(node) {
    // Check if the right-hand side of the assignment is an identifier (simple variable)
    if (!node || !node.type === "Identifier") {
      return false;
    }

    return true;
  },

  isCallbackExpressionWithoutModifyingState(node) {
    if (!node || !node.type === "ArrowFunctionExpression") {
      return false;
    }

    const params = node.params;

    if (!params.length) {
      return false;
    }

    const body = node.body;

    if (!body || !body.type === "BlockStatement") {
      return false;
    }

    return !body.body.some(statement => {
      const { type } = statement;

      return type === "AssignmentExpression";
    });
  },

  isPromiseChainWithoutModifyingState(node, parserServices) {
    if (
      !Array.isArray(node) ||
      node.length < 2 ||
      !node[node.length - 1].type === "FunctionExpression" ||
      !parserServices ||
      !parserServices.typeChecker ||
      !parserServices.typeChecker.isFunctionDeclaration(node[node.length - 1])
    ) {
      return false;
    }

    // Traverse to the last promise chain in the expression
    for (let I = node.length - 2; I >= 0; i--) {
      if (node[i].type !== "CallExpression" || !node[i].callee.object.type !== "Identifier" || node[i].callee.object.name !== "Promise") {
        return false;
      }
    }

    const isPromiseThenMethod = parserServices.typeChecker.getMethodFromPrototype("Promise.prototype.then");

    if (!isPromiseThenMethod) {
      return false;
    }

    const lastFnNode = node[node.length - 1];
    const lastFnParams = lastFnNode.params;

    return (
      lastFnNode.id &&
      lastFnParams.length === 1 &&
      parserServices.typeChecker.getFunctionIdentifier(lastFnNode.id.name) === isPromiseThenMethod.id ||
      lastFnParams.length === 2 &&
      parserServices.typeChecker.getFunctionIdentifier(lastFnParams[1].name) === isPromiseThenMethod.id
    );
  }
};

module.exports = VueParserUtils;
``` 

