     env: {
       "vue-jsx": true
     },
     rules: {
       "custom-vuereact-hooks": (node) => {
         // Verifica si se encuentra en el hook de ciclo de vida actualizado (Updated)
         if (
           !node.parent ||
           !node.parent.parent ||
           node.parent.parent.type !== "ObjectExpression" ||
           !node.parent.key.value !== "updated"
         ) {
           return;
         }

         // Verifica si el método modifica el estado interno del componente
         const hasSetState = (methodName) =>
           node.find(`Property[name="${methodName}"]`).some(
             (property) =>
               property.parent.type === "MethodDefinition" &&
               property.parent.value.body.type === "BlockStatement" &&
               property.parent.value.body.leadingStatements.filter(
                 (statement) =>
                   statement.type === "ExpressionStatement" &&
                   statement.expression.type === "AssignmentExpression" &&
                   statement.expression.operator === "=" &&
                   statement.expression.left.type === "MemberExpression" &&
                   statement.expression.left.object.type === "ThisExpression"
               ).length > 0
           );

         // Verifica si el método llama a otros métodos que modifiquen el estado interno del componente
         const hasDependencyMethods = (methodName) =>
           node.find(`CallExpression[callee.name="${methodName}"]`).some(
             (call) =>
               call.parent.type === "ExpressionStatement" &&
               call.parent.expression.type === "AssignmentExpression" &&
               call.parent.expression.operator === "=" &&
               call.parent.expression.left.type === "MemberExpression" &&
               call.parent.expression.left.object.type === "ThisExpression" &&
               hasSetState(call.arguments[0].name)
           );

         // Obtiene todos los métodos presentes en el hook de ciclo de vida actualizado
         const methods = node.find("Property[key.name='updated']", {
           parent: { type: "MethodDefinition" }
         });

         methods.filter((method) => method.value.body.body.length > 0).forEach(
           (method) => {
             if (hasSetState(method.key.name)) {
               eslint.utils.report({
                 node,
                 message: `Method "${method.key.name}" modifies internal state and should be moved to a computed property.`
               });
             }
             method.value.body.body.forEach((statement) => {
               if (
                 statement.type === "ExpressionStatement" &&
                 statement.expression.type === "AssignmentExpression" &&
                 statement.expression.operator === "=" &&
                 statement.expression.left.type === "MemberExpression" &&
                 statement.expression.left.object.type === "ThisExpression"
               ) {
                 eslint.utils.report({
                   node: statement.expression.left,
                   message: `Internal state modification detected in method "${method.key.name}". Move the creation of computed state to the computed property.`
                 });
               }
             });
             methods.filter((dependencyMethod) => {
               return (
                 dependencyMethod !== method &&
                 dependencyMethod.value.body.body.length > 0 &&
                 hasDependencyMethods(dependencyMethod.key.name)
               );
             }).forEach((dependencyMethod) => {
               dependencyMethod.value.body.body.forEach((statement) => {
                 if (
                   statement.type === "ExpressionStatement" &&
                   statement.expression.type === "AssignmentExpression" &&
                   statement.expression.operator === "=" &&
                   statement.expression.left.type === "MemberExpression" &&
                   statement.expression.left.object.type === "ThisExpression"
